def ordinalSpaceAbsorptionIsometry (γ κ : Ordinal.{u}) (hκ : Ordinal.omega0 ≤ κ)
    (hγκ : γ + κ = κ) : OrdinalC 𝕜 γ × OrdinalC 𝕜 κ ≃ₗᵢ[𝕜] OrdinalC 𝕜 κ :=
  (ordinalSpaceAddIsometry γ κ hκ).symm.trans (ordinalSpaceCongrIsometry hγκ)

